  /** The eye turret's opening and the pupil that sits in it. */
  eye: { x: 85.3, y: 112.5, r: 35.3 },
  pupil: { rx: 12.2, ry: 14.3 },
  /** Where the tongue comes from, the cheek that blushes and the feet (the point he squashes toward). */
